// The generated native model retains protobuf enum values. Metrics consume
// Go's internal task-list kinds, including nil/unknown mapping to normal.
fn metric_task_list(list: &n::api::TaskList) -> (String, Option<i32>) {
    (
        metric_string(&list.name),
        Some(i32::from(crate::matching_handler_native::persistence_kind(
            list.kind,
        ))),
    )
}

fn record_forwarded(
    metrics: &crate::matching_metrics::MatchingMetrics,
    forwarded_from: &GoString,
    domain: Option<&str>,
    list: Option<(&str, Option<i32>)>,
    task_type: &'static str,
    isolation_group: String,
) {
    if !forwarded_from.is_empty() {
        metrics.forwarded_per_task_list(&crate::matching_metrics::PollMetricContext {
            domain: domain.unwrap_or_default().to_owned(),
            task_list: list.map_or("", |(name, _)| name).to_owned(),
            task_list_kind: list.and_then(|(_, kind)| kind).unwrap_or_default(),
            task_type,
            poller_isolation_group: isolation_group,
        });
    }
}

// Control methods do not currently pass deadlines to their queue lookup. Bound
// their asynchronous work here; dropping the lookup leaves dispatched startup
// detached while cancelling a still-pending ownership admission.
async fn control_with_deadline<F, T>(
    deadline: Option<tokio::time::Instant>,
    future: F,
) -> Result<T, Status>
where
    F: std::future::Future<Output = Result<T, Status>>,
{
    match deadline {
        Some(deadline) if tokio::time::Instant::now() >= deadline => {
            Err(Status::internal("context deadline exceeded"))
        }
        Some(deadline) => tokio::time::timeout_at(deadline, future)
            .await
            .unwrap_or_else(|_| Err(Status::internal("context deadline exceeded"))),
        None => future.await,
    }
}

async fn observe<F, T>(
    metrics: &crate::matching_metrics::MatchingMetrics,
    method: &'static str,
    domain: Option<&str>,
    list: Option<(&str, Option<i32>)>,
    context: crate::matching_metrics::InboundMetricContext,
    future: F,
) -> Result<T, Status>
where
    F: std::future::Future<Output = Result<T, Status>>,
{
    metrics
        .matching_request(method, domain, list, Some(context), future)
        .await
}

// Convert only for the text-valued metric sink. Its sanitizer must see one
// rune per invalid byte, as Go tally does; diagnostic quoting changes labels.
fn metric_string(value: &GoString) -> String {
    value.go_rune_string()
}

